import type { Querier } from "../db/migrate.js";
import type { ApprovalBinding, ApprovalChange } from "./approvals.js";
import { labelWithId, quoted } from "./approvallabels.js";

/**
 * admin-step-up for machine identities, their credentials and OIDC
 * bindings (ADR-0054 Decision 5, step 4.5): what an approval binds for
 * each operation, per the binding catalogue, and the summary its approver
 * reads. None of these requests carries a secret: a new credential's token
 * is generated by the server and never bound. Each binds the query `{}`
 * (no route reads one), and no expected version: identities and OIDC
 * bindings are unversioned, and their ids pin them.
 *
 * - identity.create: target the Organization; body `name`, `kind`,
 *   `credentialTtlSeconds` and `credentialMaxUses` as requested (`null`
 *   when left out), and `effectiveTtlSeconds`, what credential-lifetime
 *   makes of the TTL (`null` = no expiry). The three credential fields bind
 *   `null` for `ci` and `agent`, which get no credential.
 * - credential.issue: target the identity; body `name`, `ttlSeconds`,
 *   `maxUses` (`null` when left out) and `effectiveTtlSeconds`.
 * - identity.reactivate: target the identity; no body. Reactivating an
 *   enabled identity changes nothing and needs no approval.
 * - oidc_binding.create: target the identity; body `issuer`, `audience`,
 *   `subject` and `claims` (a left-out object binds `{}`, which matches the
 *   same tokens; keys are sorted by the canonical form).
 * - oidc_binding.delete: target the identity and the binding; no body.
 */

/** A machine identity of the Organization, as a summary names it. */
export interface MachineIdentityRef {
  id: string;
  name: string;
  kind: string;
  disabled: boolean;
  suspendedByDeletion: boolean;
}

/** A machine identity of the Organization, read without a lock; null when there is none. */
export async function readMachineIdentity(db: Querier, organizationId: string, identityId: string): Promise<MachineIdentityRef | null> {
  const row = (await db.query(
    "SELECT id, name, kind, disabled, suspended_by_deletion FROM identities WHERE id = $1 AND organization_id = $2 AND kind <> 'human'",
    [identityId, organizationId],
  )).rows[0] as { id: string; name: string; kind: string; disabled: boolean; suspended_by_deletion: string | null } | undefined;
  return row ? { id: row.id, name: row.name, kind: row.kind, disabled: row.disabled, suspendedByDeletion: row.suspended_by_deletion !== null } : null;
}

/** 86400 -> "1 day", 5400 -> "90 minutes": a lifetime in seconds, in words (as the dashboard writes them). */
export function durationWords(seconds: number): string {
  const unit = (n: number, word: string) => `${n} ${word}${n === 1 ? "" : "s"}`;
  if (seconds % 86_400 === 0) return unit(seconds / 86_400, "day");
  if (seconds % 3_600 === 0) return unit(seconds / 3_600, "hour");
  if (seconds % 60 === 0) return unit(seconds / 60, "minute");
  return unit(seconds, "second");
}

const expiryWords = (ttlSeconds: number | null) => (ttlSeconds === null ? "never" : `after ${durationWords(ttlSeconds)}`);
const usesWords = (maxUses: number | null) => (maxUses === null ? "unlimited" : `${maxUses} use${maxUses === 1 ? "" : "s"}`);
const added = (field: string, to: string): ApprovalChange => ({ field, from: null, to, loosens: false });

/** identity.create, with the TTL credential-lifetime decided (undefined: no expiry, or no credential). */
export function identityCreateBinding(
  org: { id: string },
  input: { name: string; kind: string; credentialTtlSeconds?: number | undefined; credentialMaxUses?: number | undefined },
  issuesCredential: boolean,
  effectiveTtlSeconds: number | undefined,
): ApprovalBinding {
  const ttl = issuesCredential ? (effectiveTtlSeconds ?? null) : null;
  const maxUses = issuesCredential ? (input.credentialMaxUses ?? null) : null;
  const changes = [added("name", quoted(input.name)), added("kind", input.kind)];
  if (issuesCredential) changes.push(added("credentialExpiry", expiryWords(ttl)), added("credentialUses", usesWords(maxUses)));
  return {
    operation: "identity.create",
    organizationId: org.id,
    target: { organizationId: org.id },
    body: {
      name: input.name,
      kind: input.kind,
      credentialTtlSeconds: issuesCredential ? (input.credentialTtlSeconds ?? null) : null,
      credentialMaxUses: maxUses,
      effectiveTtlSeconds: ttl,
    },
    query: {},
    expectedVersion: null,
    summary: {
      title: issuesCredential
        ? `Create machine identity ${quoted(input.name)} (${input.kind}), with a credential that ${ttl === null ? "never expires" : `expires ${expiryWords(ttl)}`}`
        : `Create machine identity ${quoted(input.name)} (${input.kind}). It gets no credential`,
      changes,
    },
  };
}

/** credential.issue for a live service identity, with the TTL credential-lifetime decided. */
export function credentialIssueBinding(
  org: { id: string },
  identity: MachineIdentityRef,
  input: { name: string; ttlSeconds?: number | undefined; maxUses?: number | undefined },
  effectiveTtlSeconds: number | undefined,
): ApprovalBinding {
  const ttl = effectiveTtlSeconds ?? null;
  const maxUses = input.maxUses ?? null;
  return {
    operation: "credential.issue",
    organizationId: org.id,
    target: { identityId: identity.id },
    body: { name: input.name, ttlSeconds: input.ttlSeconds ?? null, maxUses, effectiveTtlSeconds: ttl },
    query: {},
    expectedVersion: null,
    summary: {
      title: `Issue credential ${quoted(input.name)} for ${identity.kind} ${labelWithId(null, identity.name, identity.id)}, ${ttl === null ? "never expiring" : `expiring ${expiryWords(ttl)}`}, ${usesWords(maxUses)}`,
      changes: [added("name", quoted(input.name)), added("credentialExpiry", expiryWords(ttl)), added("credentialUses", usesWords(maxUses))],
    },
  };
}

/** identity.reactivate of a disabled identity. */
export function identityReactivateBinding(org: { id: string }, identity: MachineIdentityRef): ApprovalBinding {
  return {
    operation: "identity.reactivate",
    organizationId: org.id,
    target: { identityId: identity.id },
    body: null,
    query: {},
    expectedVersion: null,
    summary: {
      title: `Reactivate machine identity ${labelWithId(null, identity.name, identity.id)}. It has no working credential until one is issued`,
      changes: [],
    },
  };
}

export interface OidcBindingInput {
  issuer: string;
  audience: string;
  subject: string;
  claims?: Record<string, string> | undefined;
}

/** oidc_binding.create on an identity. */
export function oidcBindingCreateBinding(org: { id: string }, identity: MachineIdentityRef, input: OidcBindingInput): ApprovalBinding {
  const claims = input.claims ?? {};
  const listed = Object.keys(claims).sort().map((k) => `${k}=${claims[k]}`);
  const changes = [added("issuer", input.issuer), added("audience", input.audience), added("subject", input.subject)];
  if (listed.length > 0) changes.push(added("claims", listed.join(", ")));
  return {
    operation: "oidc_binding.create",
    organizationId: org.id,
    target: { identityId: identity.id },
    // canonicalJson sorts the claims' keys.
    body: { issuer: input.issuer, audience: input.audience, subject: input.subject, claims },
    query: {},
    expectedVersion: null,
    summary: {
      title: `Let tokens from ${input.issuer} with subject ${input.subject} act as ${labelWithId(null, identity.name, identity.id)}`,
      changes,
    },
  };
}

/** A live OIDC binding of an identity, as its removal's summary names it. */
export interface OidcBindingRef {
  id: string;
  issuer: string;
  audience: string;
  subject: string;
}

/** A live OIDC binding of the identity in the Organization, read without a lock; null when there is none. */
export async function readOidcBinding(db: Querier, organizationId: string, identityId: string, bindingId: string): Promise<OidcBindingRef | null> {
  const row = (await db.query(
    `SELECT id, issuer, audience, subject FROM oidc_bindings
     WHERE id = $1 AND organization_id = $2 AND identity_id = $3 AND revoked_at IS NULL`,
    [bindingId, organizationId, identityId],
  )).rows[0] as OidcBindingRef | undefined;
  return row ?? null;
}

/** oidc_binding.delete of a live binding. */
export function oidcBindingDeleteBinding(org: { id: string }, identity: MachineIdentityRef, binding: OidcBindingRef): ApprovalBinding {
  return {
    operation: "oidc_binding.delete",
    organizationId: org.id,
    target: { identityId: identity.id, oidcBindingId: binding.id },
    body: null,
    query: {},
    expectedVersion: null,
    summary: {
      title: `Remove the OIDC binding ${binding.issuer} / ${binding.subject} from ${labelWithId(null, identity.name, identity.id)}`,
      changes: [],
    },
  };
}
